Update Birth Record.code:
// Update a birth record by its document number.
post(
  // 1) Path including the record's document number.
  `/api/v1/UserManagementService/integrations/registrations/birth/${$.data.documentNumber}`,
  // 2) Fields to update (status, region_id and district_id are required).
  {
    status: 'COMPLETE',
    region_id: $.data.regionId,
    district_id: $.data.districtId,
    father_first_name: $.data.father.firstName,
    father_last_name: $.data.father.lastName,
    father_national_id_type: 'GHANA CARD',
    father_national_id_number: $.data.father.ghanaCardNumber,
  }
);

Get Districts For Region.code:
// Fetch a coded lookup list. This lookup is a POST, but it only reads.
post('/api/v1/UserManagementService/integrations/utility', {
  // COUNTRY, REGION, DISTRICT, REGISTRY, TOWN, GENDER, BIRTH_TYPE, ...
  utility_type: 'DISTRICT',
  region_id: $.data.regionId, // required for DISTRICT
});
